  renderTo(target){target=Math.max(0,Math.min(this.index.total,Math.floor(target)));if(target<this.rendered)this.resetLayers();while(this.rendered<target&&this.commandIndex<this.doc.commands.length){const c=this.doc.commands[this.commandIndex],g=this.geometry[this.commandIndex];this.drawUnit(c,this.unitIndex);this.unitIndex++;this.rendered++;if(this.unitIndex===g.drawingUnits){this.ink.getContext('2d').restore();this.applyInk(this.surfaces.get(c.layer),c,g);this.inkActive=false;this.ink.getContext('2d').clearRect(...g.bounds);}if(this.unitIndex>=g.units){this.unitIndex=0;this.commandIndex++;}}this.cursor=target;this.composite();this.emit('frame');}
  play({single=false}={}){if(!this.index.total)return;if(this.playing)return;if(this.cursor>=this.index.total)this.renderTo(0);const stopAt=single?this.index.ends[this.commandIndex]:this.index.total;this.playing=true;this.emit('change');let last=performance.now(),fraction=0;const token=++this.generation;const tick=now=>{if(!this.playing||token!==this.generation)return;fraction+=Math.min(now-last,80)*(single?1:this.speed)*.18;last=now;const n=Math.floor(fraction);fraction-=n;this.renderTo(Math.min(stopAt,this.cursor+n));if(this.cursor>=stopAt){this.pause();if(this.cursor>=this.index.total)this.emit('complete');return;}this.raf=requestAnimationFrame(tick);};this.raf=requestAnimationFrame(tick);}
